$('#sendMoneyBtn').onclick=async()=>{if(trader()==='guest')return toast('Connect wallet first');const recipient=prompt('Recipient Stocklana identity / Solana address'),amount=Number(prompt('USDC amount','10')||0);if(!recipient||amount<=0)return;const r=await fetch('/api/vault/transfer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({trader:trader(),recipient,amount,asset:'USDC'})}),j=await r.json();if(!r.ok)return toast(j.error||'Transfer failed');toast('Internal transfer settled');loadVault()};
