async function buyUnderlying(a){if(!sessionToken||!wallet?.provider)return toast('Authenticate wallet first');const usdc=Number(prompt(`USDC to exchange for ${a.symbol}`,'25')||0);if(usdc<=0)return;try{toast('Building Jupiter order');const r=await fetch('/api/prestocks/order',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mint:a.contract_address,side:'BUY',usdcAmount:usdc})}),o=await r.json();if(!r.ok)throw new Error(o.error||'order_failed');if(!o.ready)return toast(o.reason||'Jupiter connector not configured');toast('Approve the PreStocks swap');const signedTransaction=await signSerializedTransaction({provider:wallet.provider,transactionBase64:o.transaction});const er=await fetch('/api/prestocks/execute',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({signedTransaction,requestId:o.requestId})}),ej=await er.json();if(!er.ok)throw new Error(ej.error||'execution_failed');toast(`Underlying executed · ${short(ej.signature||ej.txid||ej.status)}`);$('#assetDialog').close()}catch(e){toast(String(e.message||e))}}
async function loadAgents(){const g=$('#agentGrid');if(!g)return;try{const d=await fetch('/api/agent-vaults').then(r=>r.json());g.innerHTML=d.vaults.slice(0,100).map(v=>`<article class="asset-card"><div class="asset-head"><span class="status live">${v.status}</span><span class="sym">${v.crypto}</span></div><h3>${v.name}</h3><small>${v.agentId}</small><div class="market-chips">${v.connectors.map(x=>`<span>${x}</span>`).join('')}</div><div class="valuation">Daily ${money(v.policy.dailySpendLimitUSDC)} · human gate ${money(v.policy.humanApprovalAboveUSDC)}</div><small>${Object.values(v.financialTokens||{}).flat?.().filter?.(x=>typeof x==='string').slice(0,5).join(' · ')||'SL-AGENT · SL-CASH · SL-POS'}</small></article>`).join('');$('#agentWeekMetrics').innerHTML=`<div><b>${d.count}</b><span>Agent Vaults</span></div><div><b>700</b><span>Week sessions</span></div><div><b>100%</b><span>Scoped identities</span></div>`}catch(e){g.innerHTML='<div class="empty-card">Agent proof unavailable</div>'}}
